<?php require_once __DIR__.'/db.php';require_once __DIR__.'/includes/auth.php';requireAdmin();$rows=$conn->query('SELECT student_name,email,course,created_at FROM students ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Students</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="standalone"><a href="dashboard.php">← Dashboard</a><h1>Students</h1><section class="panel"><table><thead><tr><th>STUDENT</th><th>EMAIL</th><th>COURSE</th><th>ADDED</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['course'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>